// Data model (LLD §2). Enumerations are text + CHECK, timestamps are timestamptz, ids are UUIDv7
// generated by the application. Migrations are generated from this file with drizzle-kit and are
// never edited after merge (NFR-REL-03).
import { sql } from 'drizzle-orm';
import {
  bigint,
  bigserial,
  boolean,
  check,
  customType,
  index,
  inet,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

export const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType() {
    return 'bytea';
  },
});

const tstz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
const createdAt = () => tstz('created_at').notNull().defaultNow();

export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey(),
    username: text('username').notNull(),
    displayName: text('display_name').notNull().default(''),
    avatarKey: text('avatar_key'),
    passwordHash: text('password_hash').notNull(),
    role: text('role', { enum: ['member', 'admin'] })
      .notNull()
      .default('member'),
    status: text('status', { enum: ['active', 'suspended'] })
      .notNull()
      .default('active'),
    storageBytes: bigint('storage_bytes', { mode: 'number' }).notNull().default(0),
    quotaBytesOverride: bigint('quota_bytes_override', { mode: 'number' }),
    lastActiveAt: tstz('last_active_at'),
    createdAt: createdAt(),
    updatedAt: tstz('updated_at').notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex('users_username_key').on(t.username),
    index('users_display_name_trgm').using('gin', sql`${t.displayName} gin_trgm_ops`),
    check('users_username_format', sql`${t.username} ~ '^[a-z0-9][a-z0-9_.]{2,29}$'`),
    check('users_role_check', sql`${t.role} in ('member','admin')`),
    check('users_status_check', sql`${t.status} in ('active','suspended')`),
    check('users_display_name_length', sql`char_length(${t.displayName}) <= 50`),
  ],
);

export const sessions = pgTable(
  'sessions',
  {
    tokenHash: bytea('token_hash').primaryKey(),
    id: uuid('id').notNull(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    client: text('client', { enum: ['web', 'mobile'] }).notNull(),
    userAgent: text('user_agent').notNull().default(''),
    createdAt: createdAt(),
    lastSeenAt: tstz('last_seen_at').notNull().defaultNow(),
    idleExpiresAt: tstz('idle_expires_at').notNull(),
    absoluteExpiresAt: tstz('absolute_expires_at').notNull(),
  },
  (t) => [
    index('sessions_user_id_idx').on(t.userId),
    uniqueIndex('sessions_id_key').on(t.id),
    check('sessions_client_check', sql`${t.client} in ('web','mobile')`),
  ],
);

export const invites = pgTable(
  'invites',
  {
    id: uuid('id').primaryKey(),
    codeHash: bytea('code_hash').notNull(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    maxUses: integer('max_uses').notNull().default(1),
    uses: integer('uses').notNull().default(0),
    autoFriend: boolean('auto_friend').notNull().default(true),
    expiresAt: tstz('expires_at').notNull(),
    revokedAt: tstz('revoked_at'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('invites_code_hash_key').on(t.codeHash),
    index('invites_created_by_idx').on(t.createdBy, t.createdAt),
    check('invites_max_uses_range', sql`${t.maxUses} between 1 and 50`),
    check('invites_uses_le_max', sql`${t.uses} >= 0 and ${t.uses} <= ${t.maxUses}`),
  ],
);

export const inviteRedemptions = pgTable(
  'invite_redemptions',
  {
    inviteId: uuid('invite_id')
      .notNull()
      .references(() => invites.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.inviteId, t.userId] })],
);

/** One row per unordered pair (BR-FRND-2). */
export const relationships = pgTable(
  'relationships',
  {
    userLow: uuid('user_low')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    userHigh: uuid('user_high')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    // 'none' is a tombstone that only carries a decline cooldown (BR-FRND-4).
    state: text('state', { enum: ['none', 'pending', 'accepted', 'blocked'] }).notNull(),
    requestedBy: uuid('requested_by'),
    blockedBy: uuid('blocked_by'),
    cooldownUntil: tstz('cooldown_until'),
    createdAt: createdAt(),
    updatedAt: tstz('updated_at').notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.userLow, t.userHigh] }),
    check('relationships_order', sql`${t.userLow} < ${t.userHigh}`),
    check('relationships_state_check', sql`${t.state} in ('none','pending','accepted','blocked')`),
    check(
      'relationships_state_fields',
      sql`(${t.state} <> 'pending' or ${t.requestedBy} is not null) and (${t.state} <> 'blocked' or ${t.blockedBy} is not null)`,
    ),
    index('relationships_low_accepted')
      .on(t.userLow)
      .where(sql`${t.state} = 'accepted'`),
    index('relationships_high_accepted')
      .on(t.userHigh)
      .where(sql`${t.state} = 'accepted'`),
  ],
);

export const instanceSettings = pgTable('instance_settings', {
  key: text('key').primaryKey(),
  value: jsonb('value').notNull(),
  updatedBy: uuid('updated_by'),
  updatedAt: tstz('updated_at').notNull().defaultNow(),
});

export const passwordResets = pgTable(
  'password_resets',
  {
    tokenHash: bytea('token_hash').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    expiresAt: tstz('expires_at').notNull(),
    usedAt: tstz('used_at'),
    createdAt: createdAt(),
  },
  (t) => [index('password_resets_user_idx').on(t.userId)],
);

/** Append-only (enforced by a trigger, see migration 0000); no FK so entries survive deletion. */
export const auditLog = pgTable(
  'audit_log',
  {
    id: bigserial('id', { mode: 'number' }).primaryKey(),
    actorId: uuid('actor_id'),
    action: text('action').notNull(),
    targetType: text('target_type'),
    targetId: text('target_id'),
    metadata: jsonb('metadata').notNull().default({}),
    ip: inet('ip'),
    createdAt: createdAt(),
  },
  (t) => [
    index('audit_log_created_at_idx').on(t.createdAt.desc()),
    index('audit_log_actor_idx').on(t.actorId),
    index('audit_log_action_idx').on(t.action),
  ],
);

export const VIDEO_STATES = [
  'queued',
  'fetching',
  'processing',
  'ready',
  'link_only',
  'failed',
  'expired',
] as const;

export const videos = pgTable(
  'videos',
  {
    id: uuid('id').primaryKey(),
    addedBy: uuid('added_by').references(() => users.id, { onDelete: 'set null' }),
    sourceKind: text('source_kind', { enum: ['link', 'upload'] }).notNull(),
    sourceUrl: text('source_url'),
    normalizedUrl: text('normalized_url'),
    platform: text('platform'),
    sha256: bytea('sha256'),
    state: text('state', { enum: VIDEO_STATES }).notNull(),
    failureReason: text('failure_reason'),
    title: text('title').notNull().default(''),
    authorHandle: text('author_handle'),
    durationMs: integer('duration_ms'),
    width: integer('width'),
    height: integer('height'),
    mediaKey: text('media_key'),
    thumbKey: text('thumb_key'),
    mediaBytes: bigint('media_bytes', { mode: 'number' }).notNull().default(0),
    createdAt: createdAt(),
    updatedAt: tstz('updated_at').notNull().defaultNow(),
    readyAt: tstz('ready_at'),
    expiredAt: tstz('expired_at'),
  },
  (t) => [
    uniqueIndex('videos_normalized_url_key')
      .on(t.normalizedUrl)
      .where(sql`${t.normalizedUrl} is not null`),
    uniqueIndex('videos_sha256_key')
      .on(t.sha256)
      .where(sql`${t.sha256} is not null`),
    index('videos_added_by_idx').on(t.addedBy),
    index('videos_state_idx').on(t.state),
    check('videos_source_kind_check', sql`${t.sourceKind} in ('link','upload')`),
    check(
      'videos_state_check',
      sql`${t.state} in ('queued','fetching','processing','ready','link_only','failed','expired')`,
    ),
    check('videos_title_length', sql`char_length(${t.title}) <= 200`),
  ],
);

/** Every member who added a video (by link or upload). Dedup reuses media, never ownership (BR-MED-4). */
export const videoAdditions = pgTable(
  'video_additions',
  {
    videoId: uuid('video_id')
      .notNull()
      .references(() => videos.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ columns: [t.videoId, t.userId] }),
    index('video_additions_user_idx').on(t.userId),
  ],
);

export const uploads = pgTable(
  'uploads',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    objectKey: text('object_key').notNull(),
    declaredBytes: bigint('declared_bytes', { mode: 'number' }).notNull(),
    contentType: text('content_type').notNull(),
    multipartId: text('multipart_id'),
    state: text('state', { enum: ['pending', 'completed', 'aborted'] })
      .notNull()
      .default('pending'),
    videoId: uuid('video_id').references(() => videos.id, { onDelete: 'set null' }),
    expiresAt: tstz('expires_at').notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index('uploads_user_idx').on(t.userId),
    check('uploads_state_check', sql`${t.state} in ('pending','completed','aborted')`),
  ],
);
